<script lang="ts">
 import { api } from './api'; import { dataUrl, nextSort } from './data-pages'; import DataTable from './ui/DataTable.svelte'; import Pagination from './ui/Pagination.svelte'; import Skeleton from './ui/Skeleton.svelte'; import ErrorState from './ui/ErrorState.svelte'; import EmptyState from './ui/EmptyState.svelte';
 let {realms}:{realms:string[]}=$props(); type Row={id:number,kind:string,realm:string,ref_id:string|null,details:{target?:string,version?:string,eol?:string},opened_at:string,notes_class:string|null,notes_url:string|null};
 let rows=$state<Row[]>([]),offset=$state(0),sort=$state('date'),order=$state('desc'),kind=$state(''),loading=$state(true),failed=$state(false),revision=$state(0);
 let url=$derived(dataUrl('/api/v1/ui/releases',realms,offset,sort,order,{kind}));
 $effect(()=>{realms.join(',');offset=0;});
 $effect(()=>{const target=url;revision;let active=true;loading=true;failed=false;api<Row[]>(target).then(data=>{if(active){rows=data;loading=false;}}).catch(()=>{if(active){failed=true;loading=false;}});return ()=>{active=false};});
 function changeSort(field:string){[sort,order]=nextSort(sort,order,field);offset=0;} function sortState(field:string):'ascending'|'descending'|'none'{return sort===field?(order==='asc'?'ascending':'descending'):'none';}
 function kindLabel(k:string){return k==='majorrelease'?'New major':k==='eol'?'End of life':'Fixes a CVE affecting you';}
</script>
<div class="page"><label>Kind <select bind:value={kind} onchange={()=>offset=0}><option value="">All watcher results</option><option value="majorrelease">New major</option><option value="eol">End of life</option><option value="releasenotecve">Fixes a CVE affecting you</option></select></label>
{#if loading}<Skeleton/>{:else if failed}<ErrorState retry={()=>revision++}/>{:else if !rows.length}<EmptyState title="No watcher results match these realms and filters."/>{:else}<DataTable label="Watcher results"><thead><tr>{#each [['target','Target'],['kind','Kind'],['realm','Realm'],['date','Recorded']] as [field,label]}<th aria-sort={sortState(field)}><button onclick={()=>changeSort(field)}>{label} ↕</button></th>{/each}<th>Release notes</th></tr></thead><tbody>{#each rows as row}<tr><td>{row.details.target ?? row.ref_id ?? 'Unknown'}{#if row.details.version}<br/><span class="mono">{row.details.version}</span>{/if}{#if row.details.eol}<br/>EOL: {row.details.eol}{/if}</td><td>{kindLabel(row.kind)}{#if row.kind==='releasenotecve' && row.ref_id}<br/><span class="mono">{row.ref_id}</span>{/if}</td><td>{row.realm}</td><td>{row.opened_at.slice(0,10)}</td><td>{row.notes_class==='gave_up'?'(notes could not be fetched)':(row.notes_class ?? 'Not classified')}</td></tr>{/each}</tbody></DataTable>{/if}
{#if !failed}<Pagination {offset} count={rows.length} {loading} change={(n)=>offset=n}/>{/if}</div>
<style>.page{margin-top:2rem}label{display:block;margin-bottom:1rem}select{margin-left:.5rem;color:var(--text);background:var(--page);border:1px solid var(--border);padding:.6rem;border-radius:6px}.mono{font-family:var(--font-mono);font-size:.85em}</style>
